mapper.select:
SELECT co.*, u.real_name AS patient_name, u.phone AS patient_phone, u.gender AS patient_gender, cp.name AS package_name, d.real_name AS doctor_name FROM check_order co LEFT JOIN sys_user u ON co.patient_id = u.id LEFT JOIN check_package cp ON co.package_id = cp.id LEFT JOIN sys_user d ON co.doctor_id = d.id WHERE co.deleted = 0
AND co.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND co.patient_id = #{query.patientId}
AND u.real_name LIKE CONCAT('%', #{query.patientName}, '%')
AND co.status = #{query.status}
AND co.check_date >= #{query.checkDateStart}
AND co.check_date <= #{query.checkDateEnd}
ORDER BY co.create_time DESC
